args:
exec k6 run --out experimental-prometheus-rw --out "json=/results/${POD_NAME}.json" - <<'K6_SCRIPT'
const PROFILE = "average-load";
const SCENARIO = {
  "executor": "constant-vus",
  "vus": 100,
  "duration": "30m",
  "gracefulStop": "15s"
};

import http from 'k6/http';
import { check, sleep } from 'k6';

const base = 'http://ecommerce-frontend';
const email = __ENV.K6_TEST_EMAIL;
const password = __ENV.K6_TEST_PASSWORD;
const testid = __ENV.POD_NAME;
const mode = __ENV.K6_MODE || 'main';

if (!email || !password || !testid || !['main', 'preflight'].includes(mode)) {
  throw new Error('K6_TEST_EMAIL, K6_TEST_PASSWORD, POD_NAME and a valid K6_MODE are required');
}

const names = ['FE_homepage', 'BE_login', 'BE_profile', 'BE_catalog'];
const thresholds = {};
for (const name of names) {
  const filter = '{name:' + name + '}';
  thresholds['http_reqs' + filter] = ['count>0'];
  thresholds['http_req_duration' + filter] = ['p(95)<1000'];
  thresholds['http_req_failed' + filter] = mode === 'preflight' ? ['rate==0'] : [
    'rate<0.01',
    { threshold: 'rate<0.20', abortOnFail: true, delayAbortEval: '30s' },
  ];
  thresholds['checks' + filter] = mode === 'preflight' ? ['rate==1'] : ['rate>=0.99'];
}

export const options = {
  systemTags: ['name'],
  tags: { testid, profile: PROFILE, mode },
  scenarios: {
    customer: mode === 'preflight'
      ? { executor: 'per-vu-iterations', vus: 1, iterations: 4, maxDuration: '1m' }
      : SCENARIO,
  },
  thresholds,
};

http.setResponseCallback(http.expectedStatuses(200));

// Each VU keeps its own token and returns to the homepage after five catalog visits.
let step = 0;
let token = '';
let catalogVisits = 0;
let firstAction = true;

function send(method, path, name, valid, body = null, headers = {}) {
  const response = http.request(method, base + path, body, {
    headers, timeout: '4s', redirects: 0, tags: { name },
  });
  return check(response, {
    'valid response': (r) => {
      if (r.status !== 200) return false;
      try { return valid(r); } catch (_) { return false; }
    },
  }, { name });
}

export default function () {
  if (firstAction && mode === 'main') sleep(Math.random() * 8);
  firstAction = false;

  if (step === 0) {
    if (send('GET', '/', names[0], (r) => /<html[\s>]/i.test(r.body || ''))) step = 1;
  } else if (step === 1) {
    const ok = send('POST', '/api/auth/login', names[1], (r) => {
      const value = r.json('token');
      if (typeof value !== 'string' || !value) return false;
      token = value;
      return true;
    }, JSON.stringify({ email, password }), { 'Content-Type': 'application/json' });
    step = ok ? 2 : 0;
  } else if (step === 2) {
    const ok = send('GET', '/api/auth/me', names[2],
      (r) => r.json('user.email') === email.trim().toLowerCase(),
      null, { Authorization: 'Bearer ' + token });
    if (!ok) token = '';
    step = ok ? 3 : 0;
  } else {
    send('GET', '/api/products', names[3], (r) => {
      const products = r.json();
      return Array.isArray(products) && products.length > 0;
    });
    if (++catalogVisits === 5) {
      catalogVisits = 0;
      token = '';
      step = 0;
    }
  }
  if (mode === 'main') sleep(1 + Math.random() * 2);
}

export function handleSummary(data) {
  const summary = { profile: PROFILE, mode, testid, scenario: options.scenarios.customer, ...data };
  const failedThresholds = Object.entries(data.metrics).flatMap(([name, metric]) =>
    Object.entries(metric.thresholds || {}).filter(([, result]) => !result.ok)
      .map(([threshold]) => name + ': ' + threshold));
  return {
    stdout: JSON.stringify({ profile: PROFILE, mode, testid, failedThresholds }) + '\n',
    ['/results/' + testid + '-summary.json']: JSON.stringify(summary, null, 2) + '\n',
  };
}
K6_SCRIPT
